import 'package:flutter/material.dart';
import 'package:scamshield/core/l10n/l10n.dart';

/// Fixed, reviewed steps. Emergency advice is never generated by AI.
enum Situation { otp, money, app, bank }

extension SituationText on Situation {
  String label(AppLocalizations l) => switch (this) {
        Situation.otp => l.situationOtp,
        Situation.money => l.situationMoney,
        Situation.app => l.situationApp,
        Situation.bank => l.situationBank,
      };

  IconData get icon => switch (this) {
        Situation.otp => Icons.password_rounded,
        Situation.money => Icons.payments_rounded,
        Situation.app => Icons.install_mobile_rounded,
        Situation.bank => Icons.account_balance_rounded,
      };

  List<String> steps(AppLocalizations l) => switch (this) {
        Situation.otp => [l.stepOtp1, l.stepOtp2, l.stepOtp3],
        Situation.money => [l.stepMoney1, l.stepMoney2, l.stepMoney3],
        Situation.app => [l.stepApp1, l.stepApp2, l.stepApp3],
        Situation.bank => [l.stepBank1, l.stepBank2, l.stepBank3],
      };
}